.stage {
  --bg: #0b0f14; --ink: #f4f6f8; --muted: #8a94a3; --accent: #5eead4; --accent-soft: #134e4a;
  position: absolute; inset: 0; overflow: hidden; background: var(--bg); color: var(--ink);
  font-family: inter, sans-serif; font-weight: 400;
}
.cam, .scene { position: absolute; inset: 0; }
.cam { animation: push 12s cubic-bezier(0.65, 0, 0.35, 1) 0s both; }
.glow {
  position: absolute; left: 1010px; top: 90px; width: 900px; height: 900px; border-radius: 50%;
  background: radial-gradient(circle, var(--accent-soft) 0%, transparent 68%); opacity: 0.55;
}
.eyebrow, .sub { position: absolute; left: 200px; margin: 0; font-family: space-grotesk, sans-serif; letter-spacing: 6px; color: var(--muted); white-space: nowrap; }
.eyebrow { top: 330px; font-size: 48px; }
.sub { top: 600px; font-size: 64px; letter-spacing: 1px; }
.head, .head2 { position: absolute; left: 200px; margin: 0; font-weight: 700; font-family: space-grotesk, sans-serif; }
.head { top: 410px; font-size: 150px; line-height: 1.05; }
.head2 { top: 420px; font-size: 110px; line-height: 1.1; }
.rule { position: absolute; left: 200px; top: 700px; width: 420px; height: 6px; background: var(--accent); transform-origin: left center; }

.in1 { animation: show 3.6s cubic-bezier(0.19, 1, 0.22, 1) 0.2s both; }
.in2 { animation: show 3.6s cubic-bezier(0.19, 1, 0.22, 1) 0.35s both; }
.in3 { animation: show 3.6s cubic-bezier(0.19, 1, 0.22, 1) 4.2s both; }
.in4 { animation: show 3.4s cubic-bezier(0.19, 1, 0.22, 1) 4.6s both; }
.in5 { animation: show 3.6s cubic-bezier(0.19, 1, 0.22, 1) 8.2s both; }
.in6 { animation: bar 3.4s cubic-bezier(0.215, 0.61, 0.355, 1) 8.6s both; }

@keyframes push { from { transform: scale(1); } to { transform: scale(1.04) translate(-24px, -10px); } }
@keyframes show { 0% { opacity: 0; transform: translateY(36px); } 14% { opacity: 1; transform: none; } 88% { opacity: 1; transform: none; } 100% { opacity: 0; transform: none; } }
@keyframes bar { 0% { transform: scaleX(0); } 20% { transform: scaleX(1); } 100% { transform: scaleX(1); } }
